import { useState, useEffect } from "react"; // Importar hooks de React
import axios from "axios"; // Importar axios para hacer peticiones HTTP
import Card from "@mui/material/Card"; // Importar componente Card de Material UI
import { useNavigate, useParams } from "react-router-dom"; // Importar hooks de navegación y parámetros de URL
import MDBox from "components/MDBox"; // Importar componente MDBox
import MDButton from "components/MDButton"; // Importar componente MDButton
import Grid from "@mui/material/Grid"; // Importar Grid de Material UI
import MDAlert from "components/MDAlert"; // Importar componente MDAlert
import MDTypography from "components/MDTypography"; // Importar componente MDTypography
import DashboardLayout from "examples/LayoutContainers/DashboardLayout"; // Importar el diseño del dashboard
import DashboardNavbar from "examples/Navbars/DashboardNavbar"; // Importar la barra de navegación del dashboard
import DataTable from "examples/Tables/DataTable"; // Importar el componente DataTable
import PropTypes from "prop-types"; // Importar PropTypes para validación de propiedades
import "../../Pruebas/pruebas.css"; // Importar estilos CSS
import * as XLSX from "xlsx";

function Expediente() {
  const navigate = useNavigate(); // Hook para navegación
  const { id } = useParams(); // Hook para obtener parámetros de la URL
  const [errorAlert, setErrorAlert] = useState({ show: false, message: "", type: "error" }); // Estado para alertas de error
  const [dataTableData, setDataTableData] = useState([]); // Estado para los datos de la tabla
  const token = sessionStorage.getItem("token"); // Obtener el token de sesión

  // Función para exportar los datos a Excel
  const exportarDatos = () => {
    // Crear un libro de trabajo (workbook)
    const workbook = XLSX.utils.book_new();

    // Crear una hoja de trabajo (worksheet) con los datos
    const worksheet = XLSX.utils.json_to_sheet(
      dataTableData.map((expediente) => ({
        "Número Expediente": expediente.nroExpediente,
        Estado: expediente.estadoTramite?.estado || "SIN ESTADO",
        "Fecha Pago Tasa 33": expediente.d10099_f_vto_aaaa_tasa33,
        "Última Fecha Pago Tasa 35": expediente.d10099_f_vto_aaaa_tasa35,
      }))
    );

    // Añadir la hoja al libro
    XLSX.utils.book_append_sheet(workbook, worksheet, "Expedientes");

    // Generar el archivo Excel
    XLSX.writeFile(workbook, `expedientes_${new Date().toISOString()}.xlsx`);
  };

  // Función para obtener datos de cuentas corrientes según la tasa
  const obtenerCuentasCorrientes = async (d10099_id, tasa) => {
    try {
      const response = await axios.post(
        `${process.env.REACT_APP_API_URL}ANT_CuentasCorrientes/Filter`, // URL de la API
        [
          { AttributeName: "d10099_id", filterValue: d10099_id }, // Usar el ID que necesitas comparar
          { AttributeName: "d10099_tasa", filterValue: tasa }, // Enviar la tasa correspondiente
        ],
        {
          headers: { Authorization: `Bearer ${token}` }, // Incluir el token en las cabeceras
        }
      );
      console.log(`Datos recibidos para la tasa ${tasa}:`, response.data); // Mostrar datos recibidos en la consola
      return response.data; // Retornar los datos recibidos
    } catch (error) {
      manejarError(error); // Manejar errores en la llamada a la API
    }
  };

  // Función para obtener expedientes
  const obtenerExpedientes = async () => {
    try {
      const response = await axios.get(`${process.env.REACT_APP_API_URL}ANT_Expedientes/GetAll`, {
        headers: { Authorization: `Bearer ${token}` }, // Incluir el token en las cabeceras
      });
      console.log("Datos de expedientes recibidos:", response.data); // Mostrar datos de expedientes en la consola
      return response.data; // Retornar los datos de expedientes
    } catch (error) {
      manejarError(error); // Manejar errores en la llamada a la API
    }
  };

  // Manejo de errores
  const manejarError = (error) => {
    if (error.response) {
      const statusCode = error.response.status; // Obtener el código de estado del error
      let errorMessage = `Error ${statusCode}: ${
        error.response.data.message || "Problema inesperado"
      }`; // Mensaje de error
      setErrorAlert({ show: true, message: errorMessage, type: "error" }); // Mostrar alerta de error
    } else {
      setErrorAlert({
        show: true,
        message: "Ocurrió un error inesperado. Por favor, inténtalo de nuevo más tarde.", // Mensaje para errores inesperados
        type: "error",
      });
    }
  };

  useEffect(() => {
    const fetchData = async () => {
      try {
        // Obtener los expedientes
        const expedientes = await obtenerExpedientes();

        // Realizar las consultas para tasa33 y tasa35 para cada expediente
        const filteredDataPromises = expedientes.map(async (expediente) => {
          // Obtener los datos para tasa33 usando el ID que necesitas comparar
          const cuentaTasa33 = await obtenerCuentasCorrientes(expediente.tasa33, 33);
          // Obtener los datos para tasa35 usando el ID que necesitas comparar
          const cuentaTasa35 = await obtenerCuentasCorrientes(expediente.tasa35, 35);

          console.log("Cuenta Tasa 33:", cuentaTasa33); // Mostrar datos de tasa33 en consola
          console.log("Cuenta Tasa 35:", cuentaTasa35); // Mostrar datos de tasa35 en consola

          // Verificar si los datos existen y extraer el valor d10099_f_vto_aaaa
          const d10099_f_vto_aaaa_tasa33 = cuentaTasa33?.find(
            (cuenta) => Number(cuenta.d10099_id) === Number(expediente.tasa33)
          )
            ? `${
                cuentaTasa33.find(
                  (cuenta) => Number(cuenta.d10099_id) === Number(expediente.tasa33)
                )?.d10099_f_pago_dd
              }/${
                cuentaTasa33.find(
                  (cuenta) => Number(cuenta.d10099_id) === Number(expediente.tasa33)
                )?.d10099_f_pago_mm
              }/${
                cuentaTasa33.find(
                  (cuenta) => Number(cuenta.d10099_id) === Number(expediente.tasa33)
                )?.d10099_f_pago_aaaa
              }`
            : "SIN PAGO";

          const d10099_f_vto_aaaa_tasa35 = cuentaTasa35?.sort((a, b) => {
            const fechaA = new Date(
              a.d10099_f_pago_aaaa,
              a.d10099_f_pago_mm - 1,
              a.d10099_f_pago_dd
            ); // Mes - 1 porque los meses son indexados desde 0
            const fechaB = new Date(
              b.d10099_f_pago_aaaa,
              b.d10099_f_pago_mm - 1,
              b.d10099_f_pago_dd
            );
            return fechaB - fechaA; // Ordenar de más reciente a más antiguo
          })[0] // Tomar el primer elemento después de ordenar
            ? `${cuentaTasa35[0].d10099_f_pago_dd}/${cuentaTasa35[0].d10099_f_pago_mm}/${cuentaTasa35[0].d10099_f_pago_aaaa}`
            : "SIN PAGO";

          console.log(
            `Expediente ID: ${expediente.idExpediente}, Fecha Vto Tasa 33: ${d10099_f_vto_aaaa_tasa33}, Fecha Vto Tasa 35: ${d10099_f_vto_aaaa_tasa35}`
          ); // Mostrar información del expediente en consola

          // Retornar el expediente junto con las fechas de vencimiento
          return {
            ...expediente,
            d10099_f_vto_aaaa_tasa33, // Fecha para la tasa33
            d10099_f_vto_aaaa_tasa35, // Fecha para la tasa35
          };
        });

        // Esperar a que todas las promesas se resuelvan y los datos se procesen
        const filteredData = await Promise.all(filteredDataPromises);

        // Actualizar el estado con los datos filtrados
        setDataTableData(filteredData);
      } catch (error) {
        manejarError(error); // Manejar cualquier error que ocurra
      }
    };

    fetchData(); // Llamar a la función para obtener los datos
  }, [token]); // Dependencia para el useEffect

  // Función para manejar la creación de un nuevo expediente
  const handleNuevoExpediente = () => {
    navigate("/ExpedienteFE/Nuevo"); // Navegar a la ruta para crear un nuevo expediente
  };

  // Función para manejar la visualización de más información sobre un expediente
  const handleVer = (rowData) => {
    if (rowData && rowData.idExpediente) {
      navigate(`/ExpedienteFE/${rowData.idExpediente}`); // Navegar a la ruta del expediente seleccionado
    } else {
      console.error("El objeto rowData o su propiedad 'idExpediente' no están definidos."); // Log de error si falta información
    }
  };

  return (
    <DashboardLayout>
      <DashboardNavbar />
      <MDBox display="flex" justifyContent="space-between">
        <MDButton variant="gradient" color="success" onClick={handleNuevoExpediente}>
          Agregar
        </MDButton>
        <MDButton variant="gradient" color="info" onClick={exportarDatos}>
          Exportar a Excel
        </MDButton>
      </MDBox>
      {errorAlert.show && ( // Mostrar alerta si hay un error
        <Grid container justifyContent="center">
          <Grid item xs={12}>
            <MDBox pt={2}>
              <MDAlert color={errorAlert.type} dismissible>
                <MDTypography variant="body2" color="white">
                  {errorAlert.message}
                </MDTypography>
              </MDAlert>
            </MDBox>
          </Grid>
        </Grid>
      )}
      <MDBox my={3}>
        <Card>
          <DataTable
            table={{
              columns: [
                { Header: "Número Expediente", accessor: "nroExpediente" },
                { Header: "Estado", accessor: "estadoTramite.estado" },
                {
                  Header: "Fecha Pago Tasa 33",
                  accessor: "d10099_f_vto_aaaa_tasa33",
                },
                {
                  Header: "Ultima Fecha Pago Tasa 35",
                  accessor: "d10099_f_vto_aaaa_tasa35",
                },
                {
                  Header: "Más Info",
                  accessor: "edit",
                  Cell: ({ row }) => (
                    <MDButton
                      variant="gradient"
                      color="info"
                      onClick={() => handleVer(row.original)}
                    >
                      Más Info
                    </MDButton>
                  ),
                },
              ],
              rows: dataTableData,
            }}
            entriesPerPage={false}
            canSearch
            show
          />
        </Card>
      </MDBox>
    </DashboardLayout>
  );
}

// Validaciones de PropTypes para asegurar que las propiedades sean del tipo correcto
Expediente.propTypes = {
  row: PropTypes.object,
  row: PropTypes.shape({
    original: PropTypes.shape({
      idExpediente: PropTypes.string.isRequired,
    }).isRequired,
  }).isRequired,
};

export default Expediente;
