// Importar componentes y librerías necesarias
import Grid from "@mui/material/Grid";
import MDBox from "components/MDBox";
import { useParams, useNavigate } from "react-router-dom";
import { useState, useEffect } from "react";
import axios from "axios";
import MDButton from "components/MDButton";
import DashboardLayout from "examples/LayoutContainers/DashboardLayout";
import DashboardNavbar from "examples/Navbars/DashboardNavbar";
import Card from "@mui/material/Card";

// Función principal del componente
function RadioEmisoraVer() {
  // Obtener el ID desde los parámetros de la URL
  const { id } = useParams();
  // Estado para almacenar los datos de la empresa
  const [prestadoresData, setPrestadoresData] = useState(null);
  // Hook de navegación para redirigir a otras páginas
  const navigate = useNavigate();
  const token = sessionStorage.getItem("token");

  // useEffect para realizar la petición GET al servidor cuando el ID cambie
  useEffect(() => {
    // Realizar la petición GET al servidor
    axios
      .get(process.env.REACT_APP_API_URL + `ANT_RadioEmisora/getbyid?id=${id}`, {
        headers: {
          Authorization: `Bearer ${token}`, // Envía el token en los headers
        },
      })
      .then((response) => {
        // Guardar los datos recibidos en el estado
        setPrestadoresData(response.data);
        console.log("Respuesta by ID:", prestadoresData);
      })
      .catch((error) => {
        console.error("Error al obtener los datos:", error);
      });
  }, [id]);

  // Función para manejar la navegación a la página de crear nueva inspección (o cualquier otra funcionalidad)
  const handleNuevoRadioEmisora = () => {
    navigate("/RadioEmisoraFE/Nuevo");
  };

  // Función para manejar la navegación a la página de editar empresa
  const handleEditarRadioEmisora = (idRadioemisora) => {
    const url = `/RadioEmisoraFE/Edit/${idRadioemisora}`;
    console.log(url);
    navigate(url);
  };

  return (
    <DashboardLayout>
      <DashboardNavbar />
      {prestadoresData && (
        <>
          <MDBox>
            <Card>
              <p className="tituloModal">{"Radio Emisora"}</p>
              <div className="contenidoCard">
                <p>
                  <b>CellId: </b>
                  {prestadoresData?.cellId ?? "N/A"}
                </p>
                <p>
                  <b>Nombre Emisora: </b>
                  {prestadoresData?.nombreEmisora ?? "N/A"}
                </p>
                <p>
                  <b>Ubicacion: </b>
                  {prestadoresData?.ubicacion ?? "N/A"}
                </p>
                <MDButton onClick={() => handleEditarRadioEmisora(prestadoresData?.idRadioemisora)}>
                  Editar
                </MDButton>
              </div>
            </Card>
          </MDBox>
          <MDBox mt={2}>
            <MDButton variant="gradient" color="success" onClick={handleNuevoRadioEmisora}>
              Agregar RadioEmisora
            </MDButton>
          </MDBox>
        </>
      )}
    </DashboardLayout>
  );
}

export default RadioEmisoraVer;
