import { useState, useEffect } from "react";
import axios from "axios";

// @mui material components
import Card from "@mui/material/Card";
import { Link, useNavigate, useParams } from "react-router-dom";

// Material Dashboard 2 PRO React components
import MDBox from "components/MDBox";
import MDButton from "components/MDButton";
import Grid from "@mui/material/Grid";
import MDAlert from "components/MDAlert";
import MDTypography from "components/MDTypography";
import PropTypes from "prop-types";
// Material Dashboard 2 PRO React examples
import DashboardLayout from "examples/LayoutContainers/DashboardLayout";
import DashboardNavbar from "examples/Navbars/DashboardNavbar";
import DataTable from "examples/Tables/DataTable";
import "../../Pruebas/pruebas.css";
import * as XLSX from "xlsx"; // Importar XLSX para exportar a Excel

function Antena() {
  const navigate = useNavigate();
  const { id } = useParams();
  const [errorAlert, setErrorAlert] = useState({ show: false, message: "", type: "error" });
  const [dataTableData, setDataTableData] = useState();
  const token = sessionStorage.getItem("token");
  useEffect(() => {
    axios
      .get(process.env.REACT_APP_API_URL + "ANT_Antenas/GetAll", {
        headers: {
          Authorization: `Bearer ${token}`, // Envía el token en los headers
        },
      })
      .then((response) => setDataTableData(response.data))
      .catch((error) => {
        if (error.response) {
          const statusCode = error.response.status;
          let errorMessage = "";
          let errorType = "error";
          if (statusCode >= 400 && statusCode < 500) {
            errorMessage = `Error ${statusCode}: Hubo un problema con la solicitud del cliente.`;
          } else if (statusCode >= 500) {
            errorMessage = `Error ${statusCode}: Hubo un problema en el servidor.`;
          }
          setErrorAlert({ show: true, message: errorMessage, type: errorType });
        } else {
          setErrorAlert({
            show: true,
            message: "Ocurrió un error inesperado. Por favor, inténtalo de nuevo más tarde.",
            type: "error",
          });
        }
      });
  }, []);
  // Función para exportar los datos a Excel
  const exportarDatos = () => {
    // Crear un libro de trabajo (workbook)
    const workbook = XLSX.utils.book_new();

    // Crear una hoja de trabajo (worksheet) con los datos
    const worksheet = XLSX.utils.json_to_sheet(
      dataTableData.map((expediente) => ({
        "Tipo de la antena": expediente.tipoAntenas?.nombre || "SIN TIPO", // Accediendo a la propiedad del objeto
        Direccion: expediente.direccion || "SIN DIRECCION", // Accediendo a la propiedad direccion
        "Codigo Sitio": expediente.codigoSitio || "SIN CÓDIGO", // Accediendo a la propiedad codigoSitio
      }))
    );

    // Añadir la hoja al libro
    XLSX.utils.book_append_sheet(workbook, worksheet, "Expedientes");

    // Generar el archivo Excel
    XLSX.writeFile(workbook, `expedientes_${new Date().toISOString()}.xlsx`);
  };

  const formatDate = (dateString) => {
    const fecha = new Date(dateString);
    const options = {
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
    };
    return fecha.toLocaleDateString("es-ES", options);
  };

  const handleNuevoAntena = () => {
    navigate("/AntenaFE/Nuevo");
  };
  const handleVer = (rowData) => {
    if (rowData && rowData.idAntena) {
      const productId = rowData.idAntena;
      const url = `/AntenaFE/${productId}`;
      navigate(url);
    } else {
      console.error("El objeto rowData o su propiedad 'id' no están definidos.");
    }
  };
  //Funcion para que cuando el campo viene vacio muestre N/A
  const displayValue = (value) => (value ? value : "N/A");

  return (
    <>
      <DashboardLayout>
        <DashboardNavbar />
        <MDBox display="flex" justifyContent="flex-end" alignItems="center">
          <MDButton variant="gradient" color="info" onClick={exportarDatos}>
            Exportar a Excel
          </MDButton>
        </MDBox>
        {errorAlert.show && (
          <Grid container justifyContent="center">
            <Grid item xs={12} lg={12}>
              <MDBox pt={2}>
                <MDAlert color={errorAlert.type} dismissible>
                  <MDTypography variant="body2" color="white">
                    {errorAlert.message}
                  </MDTypography>
                </MDAlert>
              </MDBox>
            </Grid>
          </Grid>
        )}
        <MDBox my={3}>
          <Card>
            <DataTable
              table={{
                columns: [
                  //{ Header: "ID", accessor: "id" },
                  { Header: "Tipo de la antena", accessor: (row) => row.tipoAntenas.nombre },
                  { Header: "Direccion", accessor: "direccion" },
                  { Header: "Codigo Sitio", accessor: "codigoSitio" },
                  {
                    Header: "Mas Info",
                    accessor: "edit",
                    Cell: ({ row }) => (
                      <MDButton
                        variant="gradient"
                        color="info"
                        onClick={() => handleVer(row.original)}
                      >
                        Mas Info
                      </MDButton>
                    ),
                  },
                ],
                rows: dataTableData,
              }}
              entriesPerPage={false}
              canSearch
              show
            />
          </Card>
        </MDBox>
      </DashboardLayout>
    </>
  );
}

Antena.propTypes = {
  row: PropTypes.object, // Add this line for 'row' prop
  "row.original": PropTypes.shape({
    id: PropTypes.number,
  }),
};

export default Antena;
