import React, { useState } from "react";
import Grid from "@mui/material/Grid";
import MDBox from "components/MDBox";
import { useParams } from "react-router-dom";
import DashboardLayout from "examples/LayoutContainers/DashboardLayout";
import DashboardNavbar from "examples/Navbars/DashboardNavbar";
import Footer from "examples/Footer";
import Formulario from "components/Formulario";

function AltaEmpresa() {
  const { id } = useParams();
  let labelTitulo = "Alta Empresa";
  if (id) {
    labelTitulo = "Editar Empresa";
  }
  const steps = [
    {
      label: "Info General",
      fields: [
        {
          type: "select",
          label: "Apoderado Legal",
          name: "idApoderado",
          apiUrl: process.env.REACT_APP_API_URL + "ANT_Apoderados/GetAll",
          valueField: "idApoderado", // Nombre del campo del valor
          optionField: "nombre",
          required: true,
        },
        { type: "number", label: "cuit", name: "cuit" },
        { type: "text", label: "Direccion", name: "direccion" },
        { type: "text", label: "RazonSocial", name: "razonSocial" },
        { type: "text", label: " Nombre Tramitante Municipal", name: "nombreTramMuni" },
        { type: "text", label: "Nombre Resp. Técnico", name: "nombreRespTec" },
        { type: "text", label: "Correo del Resp. Téc.", name: "respTecCorreo" },
        { type: "text", label: "Correo del Tramitante Municipal", name: "tramMuniCorreo" },
        {
          type: "select",
          label: "Vigente",
          name: "vigente",
          customOptions: [
            { value: "S", label: "Sí" },
            { value: "N", label: "No" },
          ],
          valueField: "value",
          optionField: "label",
          required: true,
        },
      ],
    },
  ];

  const apiUrl = process.env.REACT_APP_API_URL + `ANT_Prestadores`;

  return (
    <DashboardLayout>
      <DashboardNavbar />
      <MDBox py={3} mb={20} height="65vh">
        <Grid container justifyContent="center" alignItems="center" sx={{ height: "100%", mt: 8 }}>
          <Grid item xs={12} lg={10}>
            <Formulario steps={steps} apiUrl={apiUrl} productId={id} />
          </Grid>
        </Grid>
      </MDBox>
    </DashboardLayout>
  );
}

export default AltaEmpresa;
