import React, { useState } from "react";
import Grid from "@mui/material/Grid";
import MDBox from "components/MDBox";
import { useParams } from "react-router-dom";
import DashboardLayout from "examples/LayoutContainers/DashboardLayout";
import DashboardNavbar from "examples/Navbars/DashboardNavbar";
import Footer from "examples/Footer";
import Formulario from "components/Formulario";

function AltaRadioEmisora() {
  const { id } = useParams();
  let labelTitulo = "Alta RadioEmisora";
  if (id) {
    labelTitulo = "Editar RadioEmisora";
  }
  const steps = [
    {
      label: "Info General",
      fields: [
        {
          type: "select",
          label: "Antena Asociada",
          name: "idAntena",
          apiUrl: process.env.REACT_APP_API_URL + "ANT_Antenas/GetAll",
          valueField: "idAntena",
          optionField: "codigoSitio",
          required: true,
        },
        { type: "text", label: "CellId", name: "cellId" },
        { type: "text", label: "Nombre Emisora", name: "nombreEmisora" },
        {
          type: "select",
          label: "Vigente",
          name: "vigente",
          customOptions: [
            { value: "S", label: "Sí" },
            { value: "N", label: "No" },
          ],
          valueField: "value",
          optionField: "label",
          required: true,
        },
      ],
    },
  ];

  const apiUrl = process.env.REACT_APP_API_URL + `ANT_RadioEmisora`;

  return (
    <DashboardLayout>
      <DashboardNavbar />
      <MDBox py={3} mb={20} height="65vh">
        <Grid container justifyContent="center" alignItems="center" sx={{ height: "100%", mt: 8 }}>
          <Grid item xs={12} lg={10}>
            <Formulario steps={steps} apiUrl={apiUrl} productId={id} />
          </Grid>
        </Grid>
      </MDBox>
    </DashboardLayout>
  );
}

export default AltaRadioEmisora;
