import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import PropTypes from "prop-types";
import axios from "axios";
import MDBox from "components/MDBox";
import Grid from "@mui/material/Grid";
import Card from "@mui/material/Card";
import Stepper from "@mui/material/Stepper";
import Step from "@mui/material/Step";
import MDTypography from "components/MDTypography";
import MDAlert from "components/MDAlert";
import StepLabel from "@mui/material/StepLabel";
import MDButton from "components/MDButton";
import Prueba from "./components/Prueba";

function Formulario({ steps, apiUrl, productId }) {
  const navigate = useNavigate();
  const [activeStep, setActiveStep] = useState(0);
  const [formData, setFormData] = useState({});
  const currentStep = steps[activeStep];
  const isLastStep = activeStep === steps.length - 1;
  const token = sessionStorage.getItem("token");
  const [alertData, setAlertData] = useState({
    show: false,
    message: "",
    type: "info",
  });

  const handleNext = () => setActiveStep(activeStep + 1);
  const handleBack = () => setActiveStep(activeStep - 1);

  const formatDateToString = (date) => {
    if (!(date instanceof Date) || isNaN(date)) {
      return null;
    }
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    const hours = String(date.getHours()).padStart(2, "0");
    const minutes = String(date.getMinutes()).padStart(2, "0");
    const seconds = String(date.getSeconds()).padStart(2, "0");

    return `${year}-${month}-${day}T${hours}:${minutes}:${seconds}`;
  };

  // Carga de datos del expediente si productId existe
  useEffect(() => {
    if (productId) {
      axios
        .get(`${apiUrl}/getbyid?id=${productId}`, {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        })
        .then((response) => {
          setFormData(response.data);
        })
        .catch((error) => {
          console.error("Error al cargar los datos del producto:", error);
        });
    } else {
      setAlertData({
        show: true,
        message: "No se proporcionó el ID del expediente para la actualización.",
        type: "error",
      });
      navigate(-1); // Redirigir si no hay productId
    }
  }, [apiUrl, productId]);

  // Función para manejar el envío del formulario y realizar el PUT
  const handleSubmit = (event) => {
    event.preventDefault();

    // Verificación de campos requeridos
    const requiredFields = currentStep.fields.filter((field) => field.required);
    const isFormValid = requiredFields.every((field) => formData[field.name]);
    const missingFields = requiredFields.filter((field) => !formData[field.name]);

    currentStep.fields.forEach((field) => {
      if (field.type === "checkbox" && !formData.hasOwnProperty(field.name)) {
        formData[field.name] = false;
      }
    });

    // Mostrar mensaje de error si faltan campos requeridos
    if (missingFields.length > 0) {
      const missingFieldNames = missingFields.map((field) => field.name).join(", ");
      setAlertData({
        show: true,
        message: `Por favor complete los campos requeridos: ${missingFieldNames}`,
        type: "error",
      });
      return;
    }

    // Validaciones personalizadas
    const customValidationErrors = currentStep.fields
      .filter((field) => field.customValidation)
      .map((field) => field.customValidation(formData[field.name], field))
      .filter((error) => error !== null);

    if (customValidationErrors.length > 0) {
      const errorMessages = customValidationErrors.join("\n");
      setAlertData({
        show: true,
        message: `Corrija los errores de validación específicos:\n${errorMessages}`,
        type: "error",
      });
      return;
    }
    // Aquí viene la modificación para convertir los valores null a ""
    const formDataToSend = new FormData();
    Object.keys(formData).forEach((key) => {
      const prefixedKey = key === "observacionesDTO" ? key : `expediente.${key}`; // Añadir el prefijo "expediente." a cada campo
      let value = formData[key];
      // Modificación: si el valor es null o undefined, se convierte a ""
      if (value === null || value === undefined) {
        value = ""; // Convertir a cadena vacía
      }
      if (value instanceof Date) {
        formDataToSend.append(prefixedKey, formatDateToString(value));
      } else if (value instanceof File) {
        formDataToSend.append(prefixedKey, value); // Añade el archivo directamente al FormData
      } else {
        formDataToSend.append(prefixedKey, value);
      }
    });
    const config = {
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "multipart/form-data",
      },
    };

    // Realizar la actualización (PUT) usando el productId
    axios
      .put(`${apiUrl}`, formDataToSend, config)
      .then((response) => {
        navigate(-1); // Redirige al usuario tras la actualización
      })
      .catch((error) => {
        if (error.response && error.response.status === 400) {
          setAlertData({
            show: true,
            message: error.response.data.error,
            type: "error",
          });
          setTimeout(() => {
            setAlertData({ show: false, message: "", type: "error" });
          }, 4000);
        } else {
          console.error("Error al enviar el formulario:", error);
        }
      });
  };

  const handleChange = (event) => {
    const { name, value } = event.target;
    setFormData((prevFormData) => ({
      ...prevFormData,
      [name]: value,
    }));
  };

  return (
    <MDBox mt={-9} mb={9}>
      {alertData.show && (
        <Grid container justifyContent="center">
          <Grid item xs={12} lg={12}>
            <MDBox pt={2} mb={4}>
              <MDAlert
                color={alertData.type}
                dismissible
                onDismiss={() => setAlertData({ show: false, message: "", type: "info" })}
              >
                <MDTypography variant="body2" color="white">
                  {alertData.message}
                </MDTypography>
              </MDAlert>
            </MDBox>
          </Grid>
        </Grid>
      )}
      <Grid container justifyContent="center">
        <Grid item xs={12} lg={12}>
          <Card>
            <MDBox mt={-3} mb={3} mx={2}>
              <Stepper activeStep={activeStep} alternativeLabel>
                {steps.map((step) => (
                  <Step key={step.label}>
                    <StepLabel>{step.label}</StepLabel>
                  </Step>
                ))}
              </Stepper>
            </MDBox>
            <MDBox p={2}>
              <MDBox>
                <Prueba
                  formData={formData}
                  handleChange={handleChange}
                  fields={currentStep.fields}
                />
              </MDBox>
              <MDBox mt={3} width="100%" display="flex" justifyContent="space-between">
                {activeStep === 0 ? (
                  <MDBox />
                ) : (
                  <MDButton variant="gradient" color="light" onClick={handleBack}>
                    back
                  </MDButton>
                )}
                <MDButton
                  variant="gradient"
                  color="dark"
                  onClick={!isLastStep ? handleNext : handleSubmit} // Cambiar handleNext por handleSubmit en el botón "send"
                >
                  {isLastStep ? "send" : "next"}
                </MDButton>
              </MDBox>
            </MDBox>
          </Card>
        </Grid>
      </Grid>
    </MDBox>
  );
}

Formulario.propTypes = {
  steps: PropTypes.arrayOf(
    PropTypes.shape({
      label: PropTypes.string.isRequired,
      fields: PropTypes.arrayOf(
        PropTypes.shape({
          type: PropTypes.string.isRequired,
          label: PropTypes.string.isRequired,
          name: PropTypes.string.isRequired,
        })
      ).isRequired,
    })
  ).isRequired,
  apiUrl: PropTypes.string.isRequired,
  productId: PropTypes.number.isRequired, // productId es obligatorio para realizar la actualización
};

export default Formulario;
