import Grid from "@mui/material/Grid";
import MDBox from "components/MDBox";
import { useParams, useNavigate } from "react-router-dom";
import { useState, useEffect } from "react";
import axios from "axios";
import MDButton from "components/MDButton";
import DashboardLayout from "examples/LayoutContainers/DashboardLayout";
import DashboardNavbar from "examples/Navbars/DashboardNavbar";
import Card from "@mui/material/Card";
import DataTable from "examples/Tables/DataTable";

// Función principal del componente
function ExpedienteVer() {
  const { id } = useParams(); // Obtener el ID del expediente desde los parámetros de la URL
  const [prestadoresData, setPrestadoresData] = useState(null); // Estado para almacenar los datos del expediente
  const [historialCambios, setHistorialCambios] = useState([]); // Estado para almacenar los cambios del expediente
  const navigate = useNavigate(); // Hook para la navegación
  const token = sessionStorage.getItem("token"); // Obtener el token de sesión

  useEffect(() => {
    // Realizar la petición GET al servidor para obtener los datos del expediente
    axios
      .get(`${process.env.REACT_APP_API_URL}ANT_Expedientes/getbyid?id=${id}`, {
        headers: {
          Authorization: `Bearer ${token}`, // Enviar el token en los headers
        },
      })
      .then((response) => {
        setPrestadoresData(response.data); // Guardar los datos recibidos en el estado
        console.log("Respuesta by ID:", response.data);
      })
      .catch((error) => {
        console.error("Error al obtener los datos:", error);
      });
  }, [id, token]); // Dependencias para el useEffect

  // Realizar la petición GET para obtener el historial de cambios del expediente
  useEffect(() => {
    axios
      .get(`${process.env.REACT_APP_API_URL}ANT_HistorialCambios/GetAll`, {
        headers: {
          Authorization: `Bearer ${token}`, // Enviar el token en los headers
        },
      })
      .then((response) => {
        const historialFiltrado = response.data.filter(
          (cambio) => cambio.idExpediente === parseInt(id)
        ); // Filtrar por el idExpediente
        setHistorialCambios(historialFiltrado); // Guardar los datos filtrados en el estado
        console.log("Historial de Cambios:", historialFiltrado);
      })
      .catch((error) => {
        console.error("Error al obtener el historial de cambios:", error);
      });
  }, [id, token]);

  // Función para manejar la navegación a la página de crear nueva inspección
  const handleNuevoantena = () => {
    navigate("/AntenaFE/Nuevo");
  };

  // Función para manejar la navegación a la página de editar empresa
  const handleEditarExpediente = (idExpediente) => {
    const url = `/ExpedienteFE/Edit/${idExpediente}`;
    navigate(url);
  };

  // Función para manejar la visualización del PDF
  const handleVerPDF = () => {
    const pdfUrl = `${process.env.REACT_APP_API_URL}ANT_Expedientes/GetPdf?id=${id}`; // Generar la URL del PDF
    window.open(pdfUrl, "_blank"); // Abrir el PDF en una nueva pestaña
  };

  return (
    <DashboardLayout>
      <DashboardNavbar />
      {prestadoresData && (
        <>
          <MDBox>
            <Card>
              <p className="tituloModal"> Numero de expediente: {""} </p>
              <div className="contenidoCard">
                <Grid container spacing={2}>
                  <Grid item xs={12} md={6}>
                    <p>
                      <b>Estado Tramite: </b>
                      {prestadoresData?.estadoTramite?.estado ?? "N/A"}
                    </p>
                    <p>
                      <b>Acometida Energia: </b>
                      {prestadoresData?.acometidaEnergia ?? "N/A"}
                    </p>
                    <p>
                      <b>Acta Asamblea: </b>
                      {prestadoresData?.actaAsamblea ?? "N/A"}
                    </p>
                    <p>
                      <b>AEnacom: </b>
                      {prestadoresData?.aEnacom ?? "N/A"}
                    </p>
                    <p>
                      <b>anac: </b>
                      {prestadoresData?.anac ?? "N/A"}
                    </p>
                    <p>
                      <b>Certificado de Dominio: </b>
                      {prestadoresData?.certificadoDominio ?? "N/A"}
                    </p>
                    <p>
                      <b>Compromiso de Desmonte: </b>
                      {prestadoresData?.compromisoDesmonte ?? "N/A"}
                    </p>
                    <p>
                      <b>Constancia de Pago: </b>
                      {prestadoresData?.constanciaPago ?? "N/A"}
                    </p>
                    <p>
                      <b>Contrato de Locacion: </b>
                      {prestadoresData?.contratoLocacion ?? "N/A"}
                    </p>
                    <p>
                      <b>Contrato Representante: </b>
                      {prestadoresData?.contratoRepresentante ?? "N/A"}
                    </p>
                    <p>
                      <b>Contrato ResponsableSH: </b>
                      {prestadoresData?.contratoResponsableSH ?? "N/A"}
                    </p>
                    <p>
                      <b>Copia ConvenioCNC: </b>
                      {prestadoresData?.copiaConvenioCNC ?? "N/A"}
                    </p>
                    <p>
                      <b>Cronograma de Obra: </b>
                      {prestadoresData?.cronogramaObra ?? "N/A"}
                    </p>
                    <p>
                      <b>cuadroPotencia: </b>
                      {prestadoresData?.cuadroPotencia ?? "N/A"}
                    </p>
                    <p>
                      <b>CuadroVerifConduc: </b>
                      {prestadoresData?.cuadroVerifConduc ?? "N/A"}
                    </p>
                    <p>
                      <b>factAmbienteBA: </b>
                      {prestadoresData?.factAmbienteBA ?? "N/A"}
                    </p>
                    <p>
                      <b>Impacto Ambiental: </b>
                      {prestadoresData?.impactoAmbiental ?? "N/A"}
                    </p>
                    <p>
                      <b>Layout Electrica: </b>
                      {prestadoresData?.layoutElectrica ?? "N/A"}
                    </p>
                    <p>
                      <b>Libre de Deuda: </b>
                      {prestadoresData?.libreDeuda ?? "N/A"}
                    </p>
                  </Grid>
                  <Grid item xs={12} md={6}>
                    <p>
                      <b>Medicion de Radiacion: </b>
                      {prestadoresData?.medicionRadiacion ?? "N/A"}
                    </p>
                    <p>
                      <b>Memoria Calculo: </b>
                      {prestadoresData?.memoriaCalculo ?? "N/A"}
                    </p>
                    <p>
                      <b>Nombre del Expediente: </b>
                      {prestadoresData?.nombreExp ?? "N/A"}
                    </p>
                    <p>
                      <b>Observaciones: </b>
                      {prestadoresData?.observaciones ?? "N/A"}
                    </p>
                    <p>
                      <b>Ordenamiento Territorial: </b>
                      {prestadoresData?.ordenamientoTerritorial ?? "N/A"}
                    </p>
                    <p>
                      <b>Permiso Ambiental: </b>
                      {prestadoresData?.permisoAmbiental ?? "N/A"}
                    </p>
                    <p>
                      <b>Presento Planos: </b>
                      {prestadoresData?.planos ?? "N/A"}
                    </p>
                    <p>
                      <b>Poder Tramite: </b>
                      {prestadoresData?.poderTramite ?? "N/A"}
                    </p>
                    <p>
                      <b>Poliza SeguroCT: </b>
                      {prestadoresData?.polizaSeguroCT ?? "N/A"}
                    </p>
                    <p>
                      <b>RegistroDGOP: </b>
                      {prestadoresData?.registroDGOP ?? "N/A"}
                    </p>
                    <p>
                      <b>Reglamento Copropiedad: </b>
                      {prestadoresData?.reglamentoCopropiedad ?? "N/A"}
                    </p>
                    <p>
                      <b>Seguridad Higiene: </b>
                      {prestadoresData?.seguridadHigiene ?? "N/A"}
                    </p>
                    <p>
                      <b>Seguro Responsabilidad Civil: </b>
                      {prestadoresData?.seguroRespCivil ?? "N/A"}
                    </p>
                    <p>
                      <b>Sistema Baliza: </b>
                      {prestadoresData?.sistBaliza ?? "N/A"}
                    </p>
                    <p>
                      <b>sistProtAtmos: </b>
                      {prestadoresData?.sistProtAtmos ?? "N/A"}
                    </p>
                    <p>
                      <b>Sistema Puesta Tierra: </b>
                      {prestadoresData?.sistPuestaTierra ?? "N/A"}
                    </p>
                    <p>
                      <b>Fecha Vencimiento Contrato: </b>
                      {prestadoresData?.fechaVencimientoContrato
                        ? new Date(prestadoresData.fechaVencimientoContrato).toLocaleDateString(
                            "es-ES"
                          )
                        : "N/A"}
                    </p>
                    <p>
                      <b>Fecha Vencimiento Seguro: </b>
                      {prestadoresData?.fechaVencimientoSeguro
                        ? new Date(prestadoresData.fechaVencimientoSeguro).toLocaleDateString(
                            "es-ES"
                          )
                        : "N/A"}
                    </p>
                  </Grid>
                </Grid>
                <MDButton
                  variant="gradient"
                  color="info"
                  onClick={handleVerPDF} // Manejar click para mostrar el PDF
                >
                  Ver PDF
                </MDButton>
                <MDButton onClick={() => handleEditarExpediente(prestadoresData?.idExpediente)}>
                  Editar
                </MDButton>
              </div>
            </Card>
          </MDBox>
          <MDBox mt={2}>
            <MDButton variant="gradient" color="success" onClick={handleNuevoantena}>
              Agregar Antena
            </MDButton>
          </MDBox>

          {/* Mostrar historial de cambios */}
          <MDBox mt={2}>
            <Card>
              <p className="tituloModal">{"Modificaciones del Expediente"}</p>
              {historialCambios.length > 0 ? (
                <DataTable
                  table={{
                    columns: [
                      { Header: "Nombre", accessor: "nombre" }, // Columna para el nombre del usuario
                      { Header: "Fecha de Cambio", accessor: "fechaCambio" }, // Columna para la fecha de cambio
                      { Header: "Estado del Tramite", accessor: "estadoTramite" }, // Columna para el estado del tramite
                      { Header: "Observaciones", accessor: "observaciones" }, // Columna para observaciones
                    ],
                    rows: historialCambios.map((cambio) => ({
                      nombre: cambio.usuario?.nombre ?? "N/A",
                      fechaCambio:
                        new Date(cambio.fechaCambio).toLocaleDateString("es-ES") ?? "N/A",
                      estadoTramite: cambio.estadoTramite?.estado ?? "N/A",
                      observaciones: cambio.observaciones?.trim() ?? "N/A",
                    })),
                  }}
                  entriesPerPage={false} // No mostrar el selector de entradas por página
                  canSearch // Permitir búsqueda
                  show // Mostrar tabla
                />
              ) : (
                <p>No hay cambios en el historial para este expediente.</p>
              )}
            </Card>
          </MDBox>
        </>
      )}
    </DashboardLayout>
  );
}

export default ExpedienteVer;
